cd /tmp && cat > glint-beauty.js <<'EOF'
const { chromium } = require('/home/lane/rblx/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/google-chrome',
    args: ['--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 860 } });
  const u = 'glam_' + Math.random().toString(36).slice(2, 6);

  await page.goto('http://localhost:3001');
  await page.waitForSelector('.auth-card');
  await page.waitForTimeout(1200); // fonts + entrance anims
  await page.screenshot({ path: '/tmp/glint-shots/n1-auth.png' });

  await page.click('#tab-register');
  await page.fill('#auth-user', u);
  await page.fill('#auth-pass', 'test1234');
  await page.click('#auth-go');
  await page.waitForSelector('.hero');
  await page.waitForTimeout(900);
  await page.screenshot({ path: '/tmp/glint-shots/n2-home.png' });

  await page.goto('http://localhost:3001/#/catalog');
  await page.waitForSelector('.item-card');
  await page.waitForTimeout(900);
  await page.screenshot({ path: '/tmp/glint-shots/n3-catalog.png' });

  await page.goto('http://localhost:3001/#/avatar');
  await page.waitForSelector('.avatar-preview canvas');
  await page.waitForTimeout(2200);
  await page.screenshot({ path: '/tmp/glint-shots/n4-avatar.png' });

  const g = await (await fetch('http://localhost:3001/api/games')).json();
  const obby = g.games.find(x => x.name === 'Tower of Bother');
  await page.goto('http://localhost:3001/#/play/' + obby.id);
  await page.waitForSelector('#game-root canvas');
  await page.waitForTimeout(2500);
  await page.mouse.move(720, 430); await page.mouse.down();
  await page.mouse.move(1000, 410, { steps: 8 }); await page.mouse.up();
  await page.waitForTimeout(600);
  await page.screenshot({ path: '/tmp/glint-shots/n5-ingame.png' });
  await page.click('#hud-leave');
  await page.waitForSelector('.game-head');

  await page.goto('http://localhost:3001/#/studio');
  await page.waitForSelector('#new-name');
  await page.fill('#new-name', 'Showcase');
  await page.click('#new-go');
  await page.waitForSelector('#studio-canvas-wrap canvas');
  await page.waitForTimeout(1500);
  await page.screenshot({ path: '/tmp/glint-shots/n6-studio.png' });

  await browser.close();
  console.log('shots done');
})();
EOF
